-- Scope classes/imports to the active academic year and link safe predecessor classes.
drop index if exists public.uq_school_classes_tenant_composite_key;
drop index if exists public.uq_school_classes_tenant_name_program;
create unique index if not exists uq_school_classes_tenant_year_composite_key on public.school_classes(institution_code,academic_year_id,composite_key) where composite_key is not null and academic_year_id is not null;
create unique index if not exists uq_school_classes_tenant_year_name_program on public.school_classes(institution_code,academic_year_id,class_name,coalesce(program_type,'')) where academic_year_id is not null;

create or replace function public.link_class_predecessors_for_year_v1(p_academic_year_id uuid)
returns integer language plpgsql security definer set search_path=public as $$declare v_code text;v_start date;v_prev uuid;v_count int:=0;begin if not has_permission(auth.uid(),'classes.manage') then raise exception 'FORBIDDEN';end if;select institution_code,starts_on into v_code,v_start from academic_years where id=p_academic_year_id and tenant_row_allowed(institution_code);if not found then raise exception 'YEAR_NOT_FOUND';end if;select id into v_prev from academic_years where institution_code=v_code and starts_on<v_start order by starts_on desc limit 1;if v_prev is null then return 0;end if;update school_classes n set predecessor_class_id=p.id from school_classes p where n.institution_code=v_code and n.academic_year_id=p_academic_year_id and n.predecessor_class_id is null and p.institution_code=v_code and p.academic_year_id=v_prev and n.grade_level is not null and p.grade_level=n.grade_level-1 and coalesce(n.section,'')=coalesce(p.section,'') and coalesce(n.program_type,'')=coalesce(p.program_type,'') and 1=(select count(*) from school_classes q where q.institution_code=v_code and q.academic_year_id=v_prev and q.grade_level=n.grade_level-1 and coalesce(q.section,'')=coalesce(n.section,'') and coalesce(q.program_type,'')=coalesce(n.program_type,''));get diagnostics v_count=row_count;return v_count;end$$;
grant execute on function public.link_class_predecessors_for_year_v1(uuid) to authenticated;

create or replace function public.import_class_summaries(p_file_name text,p_rows jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$declare r jsonb;v_id uuid;v_count integer:=0;v_code text;v_year uuid;v_grade smallint;v_section text;v_name text;v_key text;begin if not has_permission(auth.uid(),'classes.manage') then raise exception 'FORBIDDEN';end if;v_code:=get_my_institution_code();if v_code is null then raise exception 'TENANT_CONTEXT_REQUIRED';end if;select id into v_year from academic_years where institution_code=v_code and active=true;if v_year is null then raise exception 'ACTIVE_ACADEMIC_YEAR_REQUIRED';end if;for r in select * from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) loop v_name:=nullif(trim(r->>'className'),'');v_grade:=nullif(substring(v_name from '^([0-9]{1,2})'),'')::smallint;v_section:=nullif(trim(regexp_replace(coalesce(v_name,''),'^[0-9]{1,2}\s*[/.-]?\s*','','g')),'');v_key:=coalesce(nullif(r->>'compositeKey',''),concat_ws(' - ',v_name,nullif(r->>'programType','')));insert into school_classes(institution_code,academic_year_id,class_name,program_type,grade_level,section,composite_key,active,source_file_name,imported_student_count) values(v_code,v_year,v_name,nullif(r->>'programType',''),v_grade,v_section,v_key,true,p_file_name,coalesce((r->>'studentCount')::integer,0)) on conflict(institution_code,academic_year_id,composite_key) where composite_key is not null and academic_year_id is not null do update set program_type=excluded.program_type,grade_level=coalesce(excluded.grade_level,school_classes.grade_level),section=coalesce(excluded.section,school_classes.section),active=true,source_file_name=excluded.source_file_name,imported_student_count=excluded.imported_student_count,updated_at=now() returning id into v_id;v_count:=v_count+1;end loop;perform link_class_predecessors_for_year_v1(v_year);return jsonb_build_object('affected_classes',v_count,'institution_code',v_code,'academic_year_id',v_year);end$$;

create or replace function public.import_eokul_roster(p_file_name text,p_file_type text,p_rows jsonb)
returns table(import_batch_id uuid,imported_students integer,affected_classes integer) language plpgsql security definer set search_path=public as $$declare v_code text;v_batch uuid;v_row jsonb;v_class_id uuid;v_key text;v_class_name text;v_program text;v_grade smallint;v_section text;v_students integer:=0;v_classes text[]:='{}';v_year uuid;begin if not is_manager_or_admin() then raise exception 'NOT_AUTHORIZED';end if;v_code:=get_my_institution_code();if v_code is null then raise exception 'TENANT_CONTEXT_REQUIRED';end if;if not exists(select 1 from institutions i where i.institution_code=v_code and i.status='active' and i.approval_status='approved') then raise exception 'TENANT_NOT_APPROVED';end if;select id into v_year from academic_years where institution_code=v_code and active=true;if v_year is null then raise exception 'ACTIVE_ACADEMIC_YEAR_REQUIRED';end if;if p_file_type not in('pdf','xlsx','xls') then raise exception 'UNSUPPORTED_FILE_TYPE';end if;if jsonb_typeof(p_rows)<>'array' then raise exception 'INVALID_ROWS';end if;insert into eokul_import_batches(institution_code,imported_by,file_name,file_type,row_count) values(v_code,auth.uid(),p_file_name,p_file_type,jsonb_array_length(p_rows)) returning id into v_batch;for v_row in select value from jsonb_array_elements(p_rows) loop v_class_name:=trim(v_row->>'className');v_program:=nullif(trim(v_row->>'programType'),'');v_grade:=coalesce(nullif(v_row->>'gradeLevel','')::smallint,nullif(substring(v_class_name from '^([0-9]{1,2})'),'')::smallint);v_section:=coalesce(nullif(trim(v_row->>'section'),''),nullif(trim(regexp_replace(v_class_name,'^[0-9]{1,2}\s*[/.-]?\s*','','g')),''));v_key:=normalize_class_key(v_class_name,v_program);if coalesce(v_class_name,'')='' or coalesce(trim(v_row->>'schoolNumber'),'')='' or coalesce(trim(v_row->>'fullName'),'')='' then raise exception 'INVALID_STUDENT_ROW';end if;insert into school_classes(institution_code,academic_year_id,class_name,program_type,grade_level,section,composite_key,source,updated_at) values(v_code,v_year,v_class_name,v_program,v_grade,v_section,v_key,'eokul',now()) on conflict(institution_code,academic_year_id,composite_key) where composite_key is not null and academic_year_id is not null do update set class_name=excluded.class_name,program_type=excluded.program_type,grade_level=coalesce(excluded.grade_level,school_classes.grade_level),section=coalesce(excluded.section,school_classes.section),source='eokul',active=true,updated_at=now() returning id into v_class_id;insert into students(institution_code,school_number,full_name,class_id,active,source,import_batch_id,updated_at) values(v_code,trim(v_row->>'schoolNumber'),trim(v_row->>'fullName'),v_class_id,true,'eokul',v_batch,now()) on conflict(institution_code,school_number) do update set full_name=excluded.full_name,class_id=excluded.class_id,active=true,source='eokul',import_batch_id=excluded.import_batch_id,updated_at=now();v_students:=v_students+1;if not(v_key=any(v_classes)) then v_classes:=array_append(v_classes,v_key);end if;end loop;perform link_class_predecessors_for_year_v1(v_year);return query select v_batch,v_students,coalesce(array_length(v_classes,1),0);end$$;

create or replace view public.class_roster_summary with(security_invoker=true) as select c.id,c.class_name,c.program_type,c.grade_level,c.section,c.composite_key,c.split_threshold,count(s.id) filter(where s.active) student_count,count(s.id) filter(where s.active)>c.split_threshold needs_split,greatest(1,ceil(count(s.id) filter(where s.active)::numeric/nullif(c.split_threshold,0)::numeric)::integer) suggested_group_count,c.academic_year_id from school_classes c left join students s on s.class_id=c.id where c.active and c.academic_year_id=(select y.id from academic_years y where y.institution_code=c.institution_code and y.active=true limit 1) group by c.id;
